contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    fallback(bytes calldata input) external payable returns (bytes memory) {
        if (input.length >= 4) {
            bytes4 sel = bytes4(input[0]) | (bytes4(bytes32(uint256(uint8(input[1]))) << 24) >> 8) | (bytes4(bytes32(uint256(uint8(input[2]))) << 16) >> 16) | (bytes4(bytes32(uint256(uint8(input[3]))) << 8) >> 24);
            if (sel == IPhiFactory.artCreateFee.selector) {
                return abi.encode(uint256(0));
            }
            if (sel == IPhiFactory.protocolFeeDestination.selector) {
                return abi.encode(address(c));
            }
        }
        revert("unhandled");
    }

    function run(uint256 artId) public payable {
        uint256 before = c.tokenIdCounter();
        uint256 tid = c.createArtFromFactory{value: 0}(artId);
        assert(
            tid == before &&
            c.getTokenIdFromFactoryArtId(artId) == tid &&
            c.getFactoryArtId(tid) == artId &&
            c.tokenIdCounter() == before + 1
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        c.pause();
        bool pausedAfter = c.paused();
        bool secondPauseReverted;
        try c.pause() { secondPauseReverted = false; } catch { secondPauseReverted = true; }
        c.unPause();
        bool pausedFinal = c.paused();
        assert(pausedAfter && secondPauseReverted && !pausedFinal);
    }

    receive() external payable {}
}

