contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    fallback() external payable {
        bytes4 sel = msg.sig;
        if (sel == bytes4(keccak256("protocolFeeDestination()"))) {
            assembly {
                mstore(0x00, address())
                return(0x00, 0x20)
            }
        }
        if (sel == bytes4(keccak256("artCreateFee()"))) {
            assembly {
                mstore(0x00, 0)
                return(0x00, 0x20)
            }
        }
        revert();
    }

    function run(uint256 artId1, uint256 artId2, uint256 amount) public payable {
        require(artId1 != artId2);
        require(address(this).balance >= amount);
        c.createArtFromFactory{value: amount}(artId1);
        c.createArtFromFactory{value: amount}(artId2);
        uint256 t1 = c.getTokenIdFromFactoryArtId(artId1);
        uint256 t2 = c.getTokenIdFromFactoryArtId(artId2);
        uint256 a1 = c.getFactoryArtId(t1);
        uint256 a2 = c.getFactoryArtId(t2);
        assert(t1 == 1 && t2 == 2 && a1 == artId1 && a2 == artId2 && t1 != t2);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    fallback() external payable {
        if (msg.sig == IPhiFactory.artCreateFee.selector) {
            bytes memory r1 = abi.encode(uint256(0));
            assembly { return(add(r1, 0x20), mload(r1)) }
        }
        if (msg.sig == IPhiFactory.protocolFeeDestination.selector) {
            bytes memory r2 = abi.encode(address(this));
            assembly { return(add(r2, 0x20), mload(r2)) }
        }
        revert();
    }

    function run(uint256 artId1, uint256 artId2, uint256 amount) public payable {
        require(artId1 != artId2);
        require(artId1 != 0 && artId2 != 0);
        c.initialize(1, 1, "v", address(this));
        c.createArtFromFactory{value: amount}(artId1);
        c.createArtFromFactory{value: amount}(artId2);
        uint256 t1 = c.getTokenIdFromFactoryArtId(artId1);
        uint256 t2 = c.getTokenIdFromFactoryArtId(artId2);
        uint256 a1 = c.getFactoryArtId(t1);
        uint256 a2 = c.getFactoryArtId(t2);
        assert(t1 == 1 && t2 == 2 && a1 == artId1 && a2 == artId2 && t1 != t2);
    }

    receive() external payable {}
}

contract InvMutTest {
