contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner) public payable {
        require(newOwner != address(0));
        c.initialize(1, 1, "v", address(this));
        address ownerBefore = c.owner();
        c.transferOwnership(newOwner);
        address pending = c.pendingOwner();
        address ownerAfterTransfer = c.owner();
        c.acceptOwnership();
        address ownerAfterAccept = c.owner();
        address pendingAfterAccept = c.pendingOwner();
        assert(
            ownerBefore == address(this) &&
            pending == newOwner &&
            ownerAfterTransfer == ownerBefore &&
            ownerAfterAccept == newOwner &&
            pendingAfterAccept == address(0)
        );
    }

    receive() external payable {}
}

