contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Acts as IPhiFactory for c: protocolFeeDestination() -> address(this),
    // artCreateFee() -> 0, artData(uint256) -> zero configuration.
    fallback(bytes calldata input) external payable returns (bytes memory) {
        bytes4 sel = bytes4(input);
        if (sel == bytes4(keccak256("protocolFeeDestination()"))) {
            return abi.encode(address(this));
        }
        if (sel == bytes4(keccak256("artData(uint256)"))) {
            return abi.encode(uint256(0), uint256(0));
        }
        return abi.encode(uint256(0));
    }

    receive() external payable {}

    function run(uint256 chainId_, uint256 credId_, uint256 artId_, uint32 bps_) public {
        require(chainId_ < 1000 && credId_ < 1000 && artId_ > 0 && bps_ > 0 && bps_ <= 10000);
        c.initialize(chainId_, credId_, "v", address(this));
        c.createArtFromFactory(artId_);
        c.updateRoyalties(1, ICreatorRoyaltiesControl.RoyaltyConfiguration(bps_, address(this)));
        ICreatorRoyaltiesControl.RoyaltyConfiguration memory cfg = c.getRoyalties(1);
        assert(cfg.royaltyBPS == bps_ && cfg.royaltyRecipient == address(this));
    }
}
